function pairsBelow(nums: number[], target: number): number {
  const a = nums.slice().sort((x, y) => x - y);
  let count = 0;
  for (let i = 0; i < a.length; i++) {
    // first index j > i with a[j] >= target - a[i]
    let lo = i + 1, hi = a.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (a[mid] < target - a[i]) lo = mid + 1; else hi = mid;
    }
    count += lo - (i + 1);
  }
  return count;
}

