  const a = nums.slice().sort((x, y) => x - y);
  let lo = 0, hi = a.length - 1, count = 0;
  while (lo < hi) {
    if (a[lo] + a[hi] < target) {
      count += hi - lo;
      lo++;
    } else {
      hi--;
    }
  }
  return count;
}

